def strip_jsonc_comments(source):
    """Remove JSONC comments while preserving comment-like text in strings."""
    out=[]; i=0; quoted=False; escaped=False
    while i<len(source):
        c=source[i]
        if quoted:
            out.append(c)
            if escaped: escaped=False
            elif c=='\\': escaped=True
            elif c=='"': quoted=False
            i+=1; continue
        if c=='"': quoted=True; out.append(c); i+=1; continue
        if c=='/' and i+1<len(source) and source[i+1]=='/':
            i+=2
            while i<len(source) and source[i] not in '\r\n': i+=1
            continue
        if c=='/' and i+1<len(source) and source[i+1]=='*':
            i+=2
            while i+1<len(source) and source[i:i+2]!='*/':
                if source[i] in '\r\n': out.append(source[i])
                i+=1
            if i+1<len(source):
                i+=2
            else:
                # Preserve invalidity when a block comment reaches EOF.
                out.append('!')
                i=len(source)
            continue
        out.append(c); i+=1
    return ''.join(out)
