def yaml_value(s):
    """Decode the common JSON-compatible YAML subset for schema checks."""
    import re
    lines=[]
    for line in s.splitlines():
        t=line.strip()
        if not t or t.startswith('#'): continue
        indent=len(line)-len(line.lstrip(' '))
        lines.append((indent,t))
    def scalar(t):
        if t in ('null','~','Null','NULL'): return None
        if t.lower() in ('true','false'): return t.lower()=='true'
        try: return json.loads(t)
        except Exception: pass
        try: return int(t)
        except Exception: pass
        try: return float(t)
        except Exception: pass
        return t.strip('"\'')
    root={}
    stack=[(-1,root)]
    for indent,t in lines:
        while len(stack)>1 and indent<=stack[-1][0]: stack.pop()
        parent=stack[-1][1]
        if t.startswith('- '):
            if not isinstance(parent,list): continue
            parent.append(scalar(t[2:].strip()))
        elif ':' in t:
            key,raw=t.split(':',1); key=key.strip().strip('"\''); raw=raw.strip()
            if not isinstance(parent,dict): continue
            if raw: parent[key]=scalar(raw)
            else:
                nxt=lines[lines.index((indent,t))+1][1] if (indent,t) in lines and lines.index((indent,t))+1<len(lines) else ''
                child=[] if nxt.startswith('- ') else {}
                parent[key]=child; stack.append((indent,child))
    return root

def schema_diagnostic(source, violation):
    path, sep, message = violation.partition(': ')
    if not sep: path, message = '', violation
    key = path.rsplit('.',1)[-1].split('[',1)[0]
    offset = 0
    if key:
        import re
        found = list(re.finditer(r'(["\']?)'+re.escape(key)+r'\1\s*:',source))
        if found:
            offset=found[-1].start()
    line=source.count('\n',0,offset)+1
    col=offset-(source.rfind('\n',0,offset)+1)+1
    label=path or '(root)'
    return f'schema: line {line}, column {col}: {label}: {message}'

def read_settings(opts):
    """Load environment and project settings; explicit options win."""
    cli=set(opts)
    env={}
    envmap={'EXCLUDE_DIRS':'exclude-dirs','EXCLUDE_FILE_TYPES':'exclude-file-types',
            'FILE_TYPES':'file-types','DEPTH':'depth','REPORTER':'reporter','GROUPBY':'groupby',
            'QUIET':'quiet','REQUIRE_SCHEMA':'require-schema','NO_SCHEMA':'no-schema',
            'SCHEMASTORE':'schemastore','SCHEMASTORE_PATH':'schemastore-path',
            'GLOBBING':'globbing','GITIGNORE':'gitignore'}
    for ek,key in envmap.items():
        value=os.environ.get('CFV_'+ek)
        if value is not None:
            env[key]=value.lower() in ('1','true','yes','on') if key in ('quiet','require-schema','no-schema','schemastore','globbing','gitignore') else value
    config_path=opts.get('config')
    if config_path:
        cp=Path(config_path)
    elif opts.get('no-config'):
        cp=None
    else:
        cp=next((d/'.cfv.toml' for d in (Path.cwd(),*Path.cwd().parents) if (d/'.cfv.toml').is_file()),None)
    config={}
    if cp:
        try:
            config=toml_loads(cp.read_text())
        except Exception as e:
            raise ValueError(f'{cp}: {e}')
    allowed={'exclude-dirs','exclude-file-types','file-types','depth','reporter','groupby','quiet',
             'require-schema','no-schema','schemastore','schemastore-path','globbing','gitignore',
             'schema-map','type-map','validators'}
    for key in config:
        if key not in allowed: raise ValueError(f'{cp}: unknown key "{key}"')
    for key,value in env.items():
        if key not in cli: opts[key]=[value] if key=='reporter' else value
    for key,value in config.items():
        if key in ('schema-map','type-map'):
            if key not in cli: opts[key]=[f'{k}:{v}' for k,v in value.items()]
            continue
        if key=='validators': continue
        if key in cli: continue
        if key=='reporter' and isinstance(value,list): opts[key]=value
        elif isinstance(value,list): opts[key]=','.join(str(x) for x in value)
        else: opts[key]=value
    return opts

