"""File type detection helpers for Config File Validator."""
from __future__ import annotations

import fnmatch
import os
import re

EXTENSIONS = {
    ".json": "json", ".jsonc": "jsonc", ".yaml": "yaml", ".yml": "yaml",
    ".toml": "toml", ".xml": "xml", ".toon": "toon", ".sarif": "sarif",
    ".hcl": "hcl", ".tf": "hcl", ".ini": "ini", ".cfg": "ini",
    ".env": "env", ".csv": "csv", ".hocon": "hocon",
    ".properties": "properties", ".editorconfig": "editorconfig",
    ".plist": "plist",
}

# Names whose syntax differs from the ordinary extension (notably JSONC).
KNOWN = {
    ".arcconfig": "json", ".watchmanconfig": "json", "composer.lock": "json",
    "bun.lock": "json", "deno.lock": "json", "flake.lock": "json",
    ".babelrc": "jsonc", ".swcrc": "jsonc", ".jshintrc": "jsonc",
    "tsconfig.json": "jsonc", "jsconfig.json": "jsonc", ".eslintrc.json": "jsonc",
    ".clang-format": "yaml", ".clang-tidy": "yaml", ".clangd": "yaml", ".gemrc": "yaml",
    "pipfile": "toml", "cargo.lock": "toml", "poetry.lock": "toml", "uv.lock": "toml", "pdm.lock": "toml",
    "pom.xml": "xml", "build.xml": "xml", "ant.xml": "xml", ".classpath": "xml", ".project": "xml",
    ".gitconfig": "ini", ".gitmodules": "ini", ".npmrc": "ini", ".pylintrc": "ini",
    ".flake8": "ini", ".curlrc": "ini", ".nanorc": "ini",
    ".editorconfig": "editorconfig",
    "justfile": "justfile", ".justfile": "justfile",
}

ALIASES = {"json": "json", "jsonc": "jsonc", "yaml": "yaml", "yml": "yaml",
           "toml": "toml", "xml": "xml", "toon": "toon", "sarif": "sarif",
           "hcl": "hcl", "tf": "hcl", "ini": "ini", "hocon": "hocon", "conf": "hocon",
           "env": "env", "csv": "csv", "properties": "properties",
           "editorconfig": "editorconfig", "plist": "plist", "justfile": "justfile"}

def normalize_type(value: str) -> str | None:
    return ALIASES.get(value.strip().lower().lstrip("."))

def _matches(path: str, pattern: str) -> bool:
    """Match validator globs, allowing ** to cross directory boundaries."""
    p = pattern.replace("\\", "/")
    s = path.replace("\\", "/")
    # Patterns are commonly relative to the traversal root while path may be
    # absolute. Try every suffix, preserving filepath-style segment boundaries.
    pieces = p.split("/")
    regex = "^"
    i = 0
    while i < len(p):
        if p.startswith("**/", i):
            regex += "(?:.*/)?"
            i += 3
            continue
        c = p[i]
        if c == "*":
            regex += "[^/]*"
        elif c == "?":
            regex += "[^/]"
        elif c == "[":
            end = p.find("]", i + 1)
            if end < 0:
                regex += r"\["
            else:
                cls = p[i + 1:end]
                if cls.startswith("!"):
                    cls = "^" + cls[1:]
                regex += "[" + cls + "]"
                i = end
        else:
            regex += re.escape(c)
        i += 1
    regex += "$"
    try:
        matcher = re.compile(regex).fullmatch
    except re.error:
        return False
    candidates = [s]
    if "/" not in p:
        candidates.append(os.path.basename(s))
    else:
        segments = s.split("/")
        candidates.extend("/".join(segments[j:]) for j in range(1, len(segments)))
    return any(matcher(candidate) is not None for candidate in candidates)

def detect_type(path: str, type_maps=()) -> str | None:
    """Return canonical format name; explicit type-map rules have precedence."""
    normalized = os.path.normpath(path).replace(os.sep, "/")
    for rule in type_maps:
        if isinstance(rule, (tuple, list)) and len(rule) == 2:
            pattern, typ = rule
        elif isinstance(rule, str) and ":" in rule:
            pattern, typ = rule.rsplit(":", 1)
        else:
            continue
        if _matches(normalized, str(pattern)):
            return normalize_type(str(typ))
    name = os.path.basename(path).lower()
    if name in KNOWN:
        return KNOWN[name]
    if name in (".env", ".env.local", ".env.production", ".env.development"):
        return "env"
    return EXTENSIONS.get(os.path.splitext(name)[1])

def type_family(file_type: str) -> str:
    value = normalize_type(file_type) or file_type.lower()
    if value == "jsonc":
        return "json"
    return value

